REPLACE MACRO ETL.M_LOAD_DAILY_SALES (P_DATE DATE) AS (
  DELETE FROM MART.SALES_DAILY_AGG WHERE SALES_DT = :P_DATE;
  INSERT INTO MART.SALES_DAILY_AGG
  SEL f.ORDER_DATE, f.STORE_ID, SUM(f.ORDER_AMT), COUNT(*)
  FROM CORE.ORDER_FACT f
  WHERE f.ORDER_DATE = :P_DATE
  GROUP BY 1, 2;
  COLLECT STATISTICS ON MART.SALES_DAILY_AGG COLUMN (SALES_DT);
);

.LOGON tdprod/etl_user,$TD_PWD;
.SET ERROROUT STDOUT
DATABASE EDW_PROD;
CREATE VOLATILE TABLE VT_CUST AS (
  SEL CUST_ID, CUST_NAME, EMAIL, SEGMENT_CD
  FROM STG.STG_CUSTOMER
  QUALIFY ROW_NUMBER() OVER (PARTITION BY CUST_ID ORDER BY LOAD_TS DESC) = 1
) WITH DATA PRIMARY INDEX (CUST_ID) ON COMMIT PRESERVE ROWS;
.IF ERRORCODE <> 0 THEN .GOTO ERR_EXIT
UPDATE CORE.CUSTOMER_DIM
SET VALID_PERIOD = PERIOD(BEGIN(VALID_PERIOD), CURRENT_DATE), IS_CURRENT = 0
WHERE CUST_ID IN (SEL CUST_ID FROM VT_CUST) AND IS_CURRENT = 1;
INSERT INTO CORE.CUSTOMER_DIM
SEL HASHBUCKET(HASHROW(CUST_ID)), CUST_ID, CUST_NAME, NULL,
    CASE SEGMENT_CD WHEN 1 THEN 'ENTERPRISE' WHEN 2 THEN 'SMB' ELSE 'CONSUMER' END,
    PERIOD(CURRENT_DATE, UNTIL_CHANGED), 1
FROM VT_CUST;
.IF ERRORCODE <> 0 THEN .GOTO ERR_EXIT
COLLECT STATISTICS ON CORE.CUSTOMER_DIM INDEX (CUST_ID);
.QUIT 0
.LABEL ERR_EXIT
.QUIT 8

REPLACE PROCEDURE ETL.SP_LOAD_ORDER_FACT (IN P_LOAD_DATE DATE, OUT P_ROWS INTEGER)
BEGIN
  DECLARE V_ERR VARCHAR(500);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    SET V_ERR = 'Load failed: ' || SQLSTATE;
    INSERT INTO ETL.LOAD_ERRORS VALUES (CURRENT_TIMESTAMP(0), 'SP_LOAD_ORDER_FACT', V_ERR);
  END;
  CREATE VOLATILE MULTISET TABLE VT_ORD AS (
    SEL o.ORDER_ID, d.CUSTOMER_KEY, o.ORDER_DT, o.ORDER_AMT
    FROM STG.STG_ORDERS o
    JOIN CORE.CUSTOMER_DIM d ON d.CUST_ID = o.CUST_ID AND d.IS_CURRENT = 1
    WHERE o.LOAD_TS (DATE) = P_LOAD_DATE
  ) WITH DATA PRIMARY INDEX (ORDER_ID) ON COMMIT PRESERVE ROWS;
  MERGE INTO CORE.ORDER_FACT t
  USING VT_ORD s ON t.ORDER_ID = s.ORDER_ID
  WHEN MATCHED THEN UPDATE SET ORDER_AMT = s.ORDER_AMT
  WHEN NOT MATCHED THEN INSERT (ORDER_ID, CUSTOMER_KEY, ORDER_DATE, ORDER_AMT)
       VALUES (s.ORDER_ID, s.CUSTOMER_KEY, s.ORDER_DT, s.ORDER_AMT);
  SET P_ROWS = ACTIVITY_COUNT;
  INSERT INTO CORE.ORDER_LINE_FACT
  SEL l.ORDER_ID, l.LINE_NBR, p.PRODUCT_KEY, l.QTY, l.NET_AMT, NULLIFZERO(0)
  FROM STG.STG_ORDER_LINES l
  JOIN CORE.PRODUCT_DIM p ON p.PROD_ID = l.PROD_ID
  WHERE l.ORDER_ID IN (SEL ORDER_ID FROM VT_ORD);
  COLLECT STATISTICS ON CORE.ORDER_FACT COLUMN (ORDER_DATE);
  DROP TABLE VT_ORD;
END;

REPLACE PROCEDURE ETL.SP_REFRESH_MART ()
BEGIN
  DELETE FROM MART.CUSTOMER_360 ALL;
  INSERT INTO MART.CUSTOMER_360
  SEL c.CUST_ID, SUM(f.ORDER_AMT), MAX(f.ORDER_DATE), NULL, c.SEGMENT
  FROM CORE.ORDER_FACT f
  JOIN CORE.CUSTOMER_DIM c ON c.CUSTOMER_KEY = f.CUSTOMER_KEY
  GROUP BY 1, 5;
  CALL DBC.SYSEXECSQL('COLLECT STATISTICS ON MART.CUSTOMER_360 COLUMN (CUST_ID)');
  EXEC ETL.M_LOAD_DAILY_SALES (CURRENT_DATE - 1);
END;

CREATE OR REPLACE PACKAGE BODY GL.PKG_PERIOD_CLOSE AS
  PROCEDURE CLOSE_PERIOD (p_period IN VARCHAR2) IS
    PRAGMA AUTONOMOUS_TRANSACTION;
    TYPE t_lines IS TABLE OF GL.GL_JOURNAL_LINES%ROWTYPE;
    v_lines t_lines;
    v_cnt   NUMBER := 0;
    CURSOR c_unbal IS
      SELECT JE_HEADER_ID, SUM(NVL(ENTERED_DR,0) - NVL(ENTERED_CR,0)) AS DIFF
      FROM GL.GL_JOURNAL_LINES
      WHERE PERIOD_NAME = p_period
      GROUP BY JE_HEADER_ID
      HAVING SUM(NVL(ENTERED_DR,0) - NVL(ENTERED_CR,0)) <> 0;
  BEGIN
    FOR r IN c_unbal LOOP
      DBMS_OUTPUT.PUT_LINE('Unbalanced journal ' || r.JE_HEADER_ID || ' diff ' || r.DIFF);
      v_cnt := v_cnt + 1;
    END LOOP;
    IF v_cnt > 0 THEN
      RAISE_APPLICATION_ERROR(-20001, 'Period ' || p_period || ' has unbalanced journals');
    END IF;
    SELECT * BULK COLLECT INTO v_lines FROM GL.GL_JOURNAL_LINES WHERE PERIOD_NAME = p_period;
    FORALL i IN 1 .. v_lines.COUNT
      INSERT INTO GL.GL_JOURNAL_LINES_HIST VALUES v_lines(i);
    UPDATE GL.GL_PERIODS SET STATUS = 'C' WHERE PERIOD_NAME = p_period;
    EXECUTE IMMEDIATE 'ALTER TABLE GL.GL_JOURNAL_LINES TRUNCATE PARTITION P_' || REPLACE(p_period, '-', '_');
    UTL_FILE.PUT_LINE(UTL_FILE.FOPEN('CLOSE_DIR', 'close_' || p_period || '.log', 'w'), 'Closed ' || SYSDATE);
    COMMIT;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      ROLLBACK;
    WHEN OTHERS THEN
      ROLLBACK;
      RAISE;
  END CLOSE_PERIOD;
END PKG_PERIOD_CLOSE;

CREATE OR REPLACE PROCEDURE AP.PRC_LOAD_INVOICES (p_batch_id IN NUMBER) AS
  v_supplier AP.AP_SUPPLIERS.SUPPLIER_ID%TYPE;
BEGIN
  MERGE INTO AP.AP_INVOICES t
  USING (SELECT INVOICE_ID, SUPPLIER_ID, INVOICE_NUM, INVOICE_DATE, INVOICE_AMOUNT
         FROM AP.AP_INVOICES_STG WHERE BATCH_ID = p_batch_id) s
  ON (t.INVOICE_ID = s.INVOICE_ID)
  WHEN MATCHED THEN UPDATE SET t.INVOICE_AMOUNT = s.INVOICE_AMOUNT
       DELETE WHERE s.INVOICE_AMOUNT = 0
  WHEN NOT MATCHED THEN INSERT (INVOICE_ID, SUPPLIER_ID, INVOICE_NUM, INVOICE_DATE, INVOICE_AMOUNT)
       VALUES (s.INVOICE_ID, s.SUPPLIER_ID, s.INVOICE_NUM, s.INVOICE_DATE, s.INVOICE_AMOUNT);
  UPDATE AP.AP_SUPPLIERS
     SET TAX_ID = NVL2(TAX_ID, UPPER(TAX_ID), 'UNKNOWN'),
         CREATED = DECODE(CREATED, NULL, SYSDATE, CREATED)
   WHERE ROWID IN (SELECT MIN(ROWID) FROM AP.AP_SUPPLIERS GROUP BY TAX_ID);
  DBMS_STATS.GATHER_TABLE_STATS('AP', 'AP_INVOICES');
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;

CREATE OR REPLACE FUNCTION GL.FN_FISCAL_PERIOD (p_date IN DATE) RETURN VARCHAR2 IS
  v_period VARCHAR2(15);
BEGIN
  SELECT PERIOD_NAME INTO v_period
  FROM GL.GL_PERIODS
  WHERE p_date BETWEEN START_DATE AND END_DATE AND ROWNUM = 1;
  RETURN v_period;
EXCEPTION
  WHEN NO_DATA_FOUND THEN RETURN TO_CHAR(ADD_MONTHS(TRUNC(p_date, 'MM'), 3), 'MON-YY');
END;
